class Solution {
    public int mySqrt(int x) {
        if (x == 0) return 0;
        int k = 1;
        // 用 long 防止 k*k 溢出
        while ((long) k * k <= x) {
            k++;
        }
        return k - 1;
    }
}

class Solution {
    public int mySqrt(int x) {
        if (x < 2) return x;

        int left = 0, right = x, ans = 0;
        while (left <= right) {
            int mid = left + (right - left) / 2;
            long sq = (long) mid * mid;   // 必须用 long 防溢出
            if (sq <= x) {
                ans = mid;      // mid 是候补答案
                left = mid + 1; // 往右找更大的
            } else {
                right = mid - 1;
            }
        }
        return ans;
    }
}

class Solution {
    public int mySqrt(int x) {
        if (x < 2) return x;
        // 牛顿迭代：t 从 x 出发，每轮 (t + x/t) / 2
        long t = x;
        while (t > x / t) {           // 用整除比较，彻底避开溢出
            t = (t + x / t) / 2;
        }
        return (int) t;
    }
}
